SELECT 'gongkao', '同比', 'kp-xingce-data-term-yoy', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "同比"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "“同”指历史同期。与上一年的同一个时期（同月、同季）相比。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "在资料分析中，只要题目不说“环比”，默认的“增长”指的就是“同比增长”。这是最常见的比较基准。特征词：“同比增长”、“比上年同期”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式"}]}, {"type": "katexBlock", "attrs": {"content": "同比增长率 = \\frac{现期量 - 历史同期基期量}{历史同期基期量}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[圈出题干时间] --> B{是否有'同'字或默认增长?}\nB -- 是 --> C[时间年份减1, 月份/季度不变]\nC --> D[回材料定位该时间的基期量]\nD --> E[套用公式进行截位直除]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 2024年2月，某市日均销售额为 500 万元，2023年2月日均销售额为 400 万元。求2024年2月日均销售额同比增长率？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "识别：问的是2024年2月的同比，基期定位到2023年2月。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "注意闰年陷阱：2024年是闰年，2月有29天；2023年是平年，2月有28天。日均销售额的计算天数不同！"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "本题直接给出了日均额，不需要再除以天数。直接代入：(500 - 400) / 400 = 100 / 400。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "结果：1/4 = 25%。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "⚠️ 致命陷阱：闰年 2 月的日均量！", "marks": [{"type": "bold"}]}, {"type": "text", "text": "如果材料给的是2月总销售额，让你求“日均销售额同比增速”，千万记得分母的天数是不一样的（28天和29天）！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "每天练习5道含时间陷阱的基期定位题，重点训练对“2月”、“第一季度”、“上半年”这三个容易存在天数变动的时间节点的敏感度。"}]}]}$$ AS jsonb), NULL, '同比的核心考点与速算。', category_node.id, CAST('["资料分析", "同比"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_term_yoy", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
